function debounce(fn, wait) {
  let t = null;
  function d(...args) {
    clearTimeout(t);
    t = setTimeout(() => { t = null; fn.apply(this, args); }, wait);
  }
  d.cancel = () => { clearTimeout(t); t = null; };
  return d;
}
module.exports = { debounce };

