function truncate(text, max) {
  if (text.length <= max) return text;
  const head = text.slice(0, max - 1);
  const i = head.search(/\s\S*$/);
  const cut = i > 0 ? head.slice(0, i) : head;
  return cut.trimEnd() + '…';
}
module.exports = { truncate };

