function createEmitter() {
  const h = {};
  return {
    on(e, fn) { (h[e] = h[e] || []).push(fn); return () => { h[e] = (h[e] || []).filter((f) => f !== fn); }; },
    emit(e, ...a) {
      const l = e === '*' ? [] : (h[e] || []).slice();
      l.forEach((f) => f(...a));
      const w = (h['*'] || []).slice();
      w.forEach((f) => f(e, ...a));
      return l.length + w.length;
    },
  };
}
module.exports = { createEmitter };

